const reports = $('Get All Reports').all();
const feedbacks = $('Get All Feedback').all();

// Calculate analytics
const totalReports = reports.length;
const avgConfidence = reports.reduce((sum, r) => sum + parseFloat(r.json.fields.confidence_score || 0), 0) / totalReports;

const totalFeedback = feedbacks.length;
const avgRating = feedbacks.reduce((sum, f) => sum + parseInt(f.json.fields.rating || 0), 0) / totalFeedback;

// Count by company
const companyCounts = {};
reports.forEach(r => {
  const company = r.json.fields.company_name || 'Unknown';
  companyCounts[company] = (companyCounts[company] || 0) + 1;
});

// Recent reports
const recentReports = reports.slice(0, 10).map(r => ({
  report_id: r.json.fields.report_id,
  company: r.json.fields.company_name,
  confidence: r.json.fields.confidence_score,
  timestamp: r.json.fields.timestamp
}));

return {
  json: {
    total_reports: totalReports,
    avg_confidence_score: avgConfidence.toFixed(2),
    total_feedback: totalFeedback,
    avg_rating: avgRating.toFixed(2),
    reports_by_company: companyCounts,
    recent_reports: recentReports,
    generated_at: new Date().toISOString()
  }
};
